 "content": "def transform(grid):
    """Summarize each 3x3 region, ignoring background colors 0 and 5."""
    h, w = len(grid), len(grid[0])
    block = 3
    out = [[0 for _ in range(w // block)] for _ in range(h // block)]
    for r in range(h // block):
        for c in range(w // block):
            for y in range(r * block, (r + 1) * block):
                for x in range(c * block, (c + 1) * block):
                    color = grid[y][x]
                    if color not in (0, 5):
                        out[r][c] = color
                        break
                if out[r][c] != 0:
                    break
    return out
